-- ============================================================================
-- Migration: Complete synchronization of marketing email templates
-- Description: Sets the final, authoritative JSON for site_settings.marketing_mail_templates:
--              - Contains all 4 templates: tool_relist, sponsored_feature, new_tool_launch, affiliate_partnership
--              - Sender: "from_name": "Toolbit AI", "from_email": "team@mail.toolbit.ai"
--              - Refined 2-line footer across all templates:
--                  * Line 1 (13.5px, #52525b): "You received this email regarding AI tool discovery and opportunities on Toolbit.ai."
--                  * Line 2 (12px, #a1a1aa): "Feel free to reply this mail or reach out to us at contact@toolbit.ai."
--                  * Clean Home & Contact links (#71717a) and © 2026 Toolbit AI copyright.
--              - Consistent lighter bold styling (font-weight: 600) on all body text and <style> tags.
--              - tool_relist specific refinements:
--                  * "If you want {{tool_name}} ({{tool_domain}}) to get more..."
--                  * Standard dark checkmarks (✓, #18181b, 14px, weight 600)
--                  * Zero margin between feature items (margin: 0, line-height: 1.5)
--                  * "A dedicated X/Twitter post featuring your tool"
--                  * Clean sign-off: "Best,\nToolbit AI\nhttps://www.toolbit.ai/"
--                  * Variables: ["{{first_name}}", "{{tool_name}}", "{{tool_domain}}"]
-- ============================================================================

INSERT INTO site_settings (key, value)
VALUES (
  'marketing_mail_templates',
  $tmpl${
    "sponsored_feature": {
      "id": "sponsored_feature",
      "name": "Sponsored Feature",
      "description": "Visibility opportunity pitch for sponsored placements and featuring on Toolbit",
      "subject": "A Visibility Opportunity for {{tool_name}} on Toolbit.ai",
      "from_name": "Toolbit AI",
      "from_email": "team@mail.toolbit.ai",
      "html": "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Transitional//EN' 'http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd'><html xmlns='http://www.w3.org/1999/xhtml' lang='en'><head><meta http-equiv='Content-Type' content='text/html; charset=UTF-8' /><meta name='viewport' content='width=device-width, initial-scale=1.0' /><meta http-equiv='X-UA-Compatible' content='IE=edge' /><title>A Visibility Opportunity for {{tool_name}} on Toolbit.ai</title><style type='text/css'>@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&display=swap');body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }body { height: 100% !important; margin: 0 !important; padding: 0 !important; width: 100% !important; background-color: #f9f8f6; font-family: 'Figtree', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }p { margin: 0 0 18px 0 !important; line-height: 1.65 !important; color: #3f3f46 !important; font-size: 15px !important; }strong { color: #18181b !important; font-weight: 600 !important; }a { color: #0d9488 !important; text-decoration: underline !important; font-weight: 500 !important; }ul, ol { margin: 0 0 20px 0 !important; padding-left: 24px !important; line-height: 1.65 !important; color: #3f3f46 !important; }li { margin-bottom: 8px !important; }@media only screen and (max-width: 600px) { .responsive-table { width: 100% !important; } .mobile-padding { padding-left: 20px !important; padding-right: 20px !important; } }</style></head><body style='margin: 0; padding: 0; background-color: #f9f8f6;'><table role='presentation' border='0' cellpadding='0' cellspacing='0' width='100%' style='background-color: #f9f8f6; width: 100%;'><tr><td align='center' style='padding: 32px 16px;'><table role='presentation' border='0' cellpadding='0' cellspacing='0' width='100%' class='responsive-table' style='max-width: 580px; background-color: #ffffff; border-radius: 12px; border: 1px solid #e4e2db; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03);'><tr><td style='padding: 32px 32px 20px 32px; background-color: #fcfbfa; border-bottom: 1px solid #f4f4f5; text-align: left;' class='mobile-padding'><a href='https://www.toolbit.ai/' target='_blank' style='text-decoration: none; display: inline-block;'><img src='https://www.toolbit.ai/logo-icon.png' alt='Toolbit.ai Logo' width='28' height='28' style='display: inline-block; vertical-align: middle; margin-right: 8px; width: 28px; height: 28px; border: 0;' /><span style='display: inline-block; vertical-align: middle; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 20px; font-weight: 750; letter-spacing: -0.8px; color: #0d9488;'>Toolbit.ai</span></a></td></tr><tr><td style='padding: 32px 32px 28px 32px; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 15px; line-height: 1.65; color: #3f3f46;' class='mobile-padding'><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>Hi {{recipient_name}},</p><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>I'm reaching out from Toolbit.ai, a discovery platform where users search, compare, and find AI tools across a wide range of categories and use cases.</p><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>While going through tools in the AI space, I came across <strong style='color: #18181b; font-weight: 600;'>{{tool_name}}</strong> and thought it would be a strong fit for the audience we're building on Toolbit - users actively looking for capable, relevant AI solutions.</p><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>As part of our ongoing efforts to support quality AI products, we're currently offering select companies additional visibility on the platform. Depending on the product and your promotional goals, this can take the form of either a complimentary featuring opportunity or a paid placement option - each designed to help <strong style='color: #18181b; font-weight: 600;'>{{tool_name}}</strong> stand out to our growing user base beyond a standard listing.</p><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>I'd be happy to walk you through what's available and help figure out which option would work best for <strong style='color: #18181b; font-weight: 600;'>{{tool_name}}</strong> at this stage.</p><p style='margin: 0 0 18px 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>Would you be open to taking a look at the details? I'd be glad to share more whenever convenient for you.</p><div style='margin: 24px 0 0 0; line-height: 1.65; color: #3f3f46; font-size: 15px;'>Best regards,<br>Toolbit AI<br>Toolbit.ai<br><a href='https://www.toolbit.ai/' style='color: #0d9488; text-decoration: underline; font-weight: 500;' target='_blank'>https://www.toolbit.ai/</a></div></td></tr><tr><td align='center' style='padding: 24px 24px 28px 24px; background-color: #fcfbfa; border-top: 1px solid #f4f4f5; text-align: center;' class='mobile-padding'><p style='margin: 0 0 0 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 13.5px !important; color: #52525b !important; line-height: 1.4 !important; text-align: center;'>You received this email regarding AI tool discovery and opportunities on Toolbit.ai.</p><p style='margin: 4px 0 12px 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 12px !important; color: #a1a1aa !important; line-height: 1.4 !important; text-align: center;'>Feel free to reply this mail or reach out to us at <a href='mailto:contact@toolbit.ai' style='color: #71717a !important; text-decoration: underline !important; font-weight: 500 !important;'>contact@toolbit.ai</a>.</p><div style='margin-bottom: 12px;'><a href='https://www.toolbit.ai/' style='color: #71717a; text-decoration: none; font-weight: 600; font-size: 12px; margin: 0 6px;' target='_blank'>Home</a> &middot; <a href='https://www.toolbit.ai/contact' style='color: #71717a; text-decoration: none; font-weight: 600; font-size: 12px; margin: 0 6px;' target='_blank'>Contact</a></div><p style='margin: 0 !important; font-family: Figtree, -apple-system, BlinkMacSystemFont, Arial, sans-serif; font-size: 11px !important; color: #94a3b8 !important; line-height: 1.4 !important; text-align: center;'>&copy; 2026 Toolbit AI. All rights reserved.</p></td></tr></table></td></tr></table></body></html>",
      "text": "Hi {{recipient_name}},\n\nI'm reaching out from Toolbit.ai, a discovery platform where users search, compare, and find AI tools across a wide range of categories and use cases.\n\nWhile going through tools in the AI space, I came across **{{tool_name}}** and thought it would be a strong fit for the audience we're building on Toolbit - users actively looking for capable, relevant AI solutions.\n\nAs part of our ongoing efforts to support quality AI products, we're currently offering select companies additional visibility on the platform. Depending on the product and your promotional goals, this can take the form of either a complimentary featuring opportunity or a paid placement option - each designed to help **{{tool_name}}** stand out to our growing user base beyond a standard listing.\n\nI'd be happy to walk you through what's available and help figure out which option would work best for **{{tool_name}}** at this stage.\n\nWould you be open to taking a look at the details? I'd be glad to share more whenever convenient for you.\n\nBest regards,\nToolbit AI\nToolbit.ai\nhttps://www.toolbit.ai/",
      "variables": ["{{recipient_name}}", "{{tool_name}}"],
      "created_at": "2026-09-02T00:00:00.000Z",
      "updated_at": "2026-09-29T12:30:00.000Z"
    },
    "new_tool_launch": {
      "id": "new_tool_launch",
      "name": "New Tool Launch",
      "description": "Launch announcement outreach for new AI tools on Toolbit",
      "subject": "Launching {{tool_name}}? Get Discovered on Toolbit",
      "from_name": "Toolbit AI",
      "from_email": "team@mail.toolbit.ai",
      "html": "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Transitional//EN' 'http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd'><html xmlns='http://www.w3.org/1999/xhtml' lang='en'><head><meta http-equiv='Content-Type' content='text/html; charset=UTF-8' /><meta name='viewport' content='width=device-width, initial-scale=1.0' /><meta http-equiv='X-UA-Compatible' content='IE=edge' /><title>Launching {{tool_name}}? Get Discovered on Toolbit</title><style type='text/css'>@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&display=swap');body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }body { height: 100% !important; margin: 0 !important; padding: 0 !important; width: 100% !important; background-color: #f9f8f6; font-family: 'Figtree', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }p { margin: 0 0 18px 0 !important; line-height: 1.65 !important; color: #3f3f46 !important; font-size: 15px !important; }strong { color: #18181b !important; font-weight: 600 !important; }a { color: #0d9488 !important; text-decoration: underline !important; font-weight: 500 !important; }ul, ol { margin: 0 0 20px 0 !important; padding-left: 24px !important; line-height: 1.65 !important; color: #3f3f46 !important; }li { margin-bottom: 8px !important; }@media only screen and (max-width: 600px) { .responsive-table { width: 100% !important; } .mobile-padding { padding-left: 20px !important; padding-right: 20px !important; } }</style></head><body style='margin: 0; padding: 0; background-color: #f9f8f6;'><table role='presentation' border='0' cellpadding='0' cellspacing='0' width='100%' style='background-color: #f9f8f6; width: 100%;'><tr><td align='center' style='padding: 32px 16px;'><table role='presentation' border='0' cellpadding='0' cellspaci